const source = $('Execute Workflow Trigger').item.json || {};

const args = source.args || source.payload?.args || {};
const payload = source.payload || {};
const message =
  source.message ||
  payload.message ||
  payload.body?.message ||
  {};

const chatId =
  source.chatId ||
  message.chat?.id ||
  payload.chatId ||
  '';

const raw = String(
  source.rawText ||
  source.text ||
  message.text ||
  payload.text ||
  ''
).trim();

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function cleanQuery(value) {
  return String(value || '')
    .trim()
    .replace(/^["'“”‘’]+|["'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

function extractSearchQuery(rawText) {
  const original = String(rawText || '').trim();
  const normalized = normalize(original);

  const prefixes = [
    'tim file',
    'search file',
    'kiem file',
    'tim trong drive',
    'find file',
    'tim tep',
    'kiem tep',
    'search drive',
    'drive search'
  ];

  for (const prefix of prefixes) {
    if (normalized.startsWith(prefix + ' ')) {
      return cleanQuery(original.slice(prefix.length + 1));
    }

    if (normalized === prefix) {
      return '';
    }
  }

  return '';
}

const query = cleanQuery(
  source.query ||
  source.fileName ||
  args.query ||
  args.fileName ||
  payload.query ||
  payload.fileName ||
  extractSearchQuery(raw)
);

const mimeType =
  source.mimeType ||
  args.mimeType ||
  payload.mimeType ||
  '';

const folderId =
  source.folderId ||
  args.folderId ||
  payload.folderId ||
  'root';

const limit = Number(
  source.limit ||
  args.limit ||
  payload.limit ||
  5
) || 5;

return [{
  json: {
    ...source,
    payload,
    message,
    chatId,
    raw,
    rawText: raw,
    text: normalize(raw),
    query,
    fileName: query,
    mimeType,
    folderId,
    limit,
    hasTarget: Boolean(query),
    response: query
      ? ''
      : '📁 <b>Tìm file trong Drive</b>\n\nVí dụ: <code>tìm file hợp đồng</code>',
  },
}];

const pickFirst = (...values) => {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  }
  return '';
};

const formatDate = (value) => {
  if (!value) return '';
  const date = new Date(value);
  return Number.isNaN(date.getTime())
    ? ''
    : date.toLocaleString('vi-VN', {
        timeZone: 'Asia/Ho_Chi_Minh',
        hour12: false,
      });
};

const getFileType = (mimeType = '') => {
  if (mimeType === 'application/vnd.google-apps.folder') return 'folder';
  if (mimeType === 'application/vnd.google-apps.document') return 'Google Docs';
  if (mimeType === 'application/vnd.google-apps.spreadsheet') return 'Google Sheets';
  if (mimeType === 'application/pdf') return 'PDF';
  if (mimeType.startsWith('image/')) return 'ảnh';
  return 'file';
};

const source = $('Prepare Action').item.json;

const rows = $input
  .all()
  .map((item) => item.json || {})
  .filter((item) => item.id || item.name)
  .sort((a, b) => {
    const timeA = new Date(a.modifiedTime || a.createdTime || 0).getTime();
    const timeB = new Date(b.modifiedTime || b.createdTime || 0).getTime();
    return timeB - timeA;
  })
  .slice(0, 3);

const query = pickFirst(source.query, source.fileName, source.rawText, source.text);

let text = '';
if (!rows.length) {
  text = query
    ? `Mia chưa tìm thấy file nào thật sự khớp với "${query}".`
    : 'Mia chưa tìm thấy file phù hợp.';
} else {
  text = query
    ? `Mia tìm thấy ${rows.length} file khá khớp với "${query}":`
    : `Mia tìm thấy ${rows.length} file phù hợp:`;
  const links = [];
  rows.forEach((file, index) => {
    const name = file.name || 'Không rõ tên';
    const link = pickFirst(file.webViewLink);
    const modified = formatDate(file.modifiedTime || file.createdTime);
    const fileType = getFileType(file.mimeType || '');
    text += `\n${index + 1}. ${name}`;
    if (fileType) text += ` — ${fileType}`;
    if (modified) text += `, cập nhật ${modified}`;
    if (link) links.push(link);
  });
  if (links.length) {
    text += '\n\nMở file:';
    links.slice(0, 3).forEach((link, index) => {
      text += `\n${index + 1}. ${link}`;
    });
  }
}

return [{ json: { chatId: source.chatId, text: text.trim() } }];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target =
  source.query ||
  source.docName ||
  source.sheetName ||
  source.fileName ||
  source.folderName ||
  source.targetName ||
  source.title ||
  source.summary ||
  source.rawText ||
  source.text ||
  '';

let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false || source.isReady === false ? 'missing_required_input' : 'not_found_or_not_applicable'
    }
  }
}];
